local MarbleStatueMaker = {}
local PRODUCTS = {
    small_bust = { name = "Majhen poprsje", marbleCost = 1, time = 3, cost = 40, artistry = 40, prestige = 3, description = "Majhen marmornat poprsje." },
    garden_statue = { name = "Vrtni kip", marbleCost = 2, chiselCost = 1, time = 5, cost = 100, artistry = 55, prestige = 6, happiness = 1, description = "Vrtni marmornat kip za vrtove." },
    life_size_statue = { name = "Naravno velik kip", marbleCost = 3, chiselCost = 1, time = 8, cost = 240, artistry = 70, prestige = 12, happiness = 2, description = "Naravno velik marmornat kip." },
    silver_accented_statue = { name = "Srebrno poudarjen kip", marbleCost = 3, silverCost = 1, chiselCost = 1, time = 11, cost = 560, artistry = 82, prestige = 20, happiness = 4, description = "Kip s srebrnimi poudarki za plemiče." },
    gold_leafed_statue = { name = "Zlatolistni kip", marbleCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, chiselCost = 1, time = 15, cost = 1200, artistry = 92, prestige = 30, happiness = 7, description = "Zlatolistni marmornat kip za visoke plemiče." },
    royal_grand_statue = { name = "Kraljevski veliki kip", marbleCost = 8, goldCost = 2, silverCost = 1, jewelCost = 2, pearlCost = 1, chiselCost = 2, time = 22, cost = 3500, artistry = 100, prestige = 60, happiness = 14, description = "Veliki kraljevski marmornat kip z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kiparska delavnica", cost = { gold = 350, wood = 140, stone = 300 }, upkeep = 9, qualityBonus = 5 },
    carving_studio = { name = "Rezbarski atelje", cost = { gold = 1200, wood = 300, stone = 600, marble = 8 }, upkeep = 30, qualityBonus = 18 },
    polishing_room = { name = "Polirnica", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, chisel = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_statue_atelier = { name = "Kraljevski atelje kipov", cost = { gold = 12000, wood = 700, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
MarbleStatueMaker.marbleStock = 18; MarbleStatueMaker.chiselStock = 12; MarbleStatueMaker.silverStock = 8; MarbleStatueMaker.goldStock = 6; MarbleStatueMaker.jewelStock = 6; MarbleStatueMaker.pearlStock = 4
MarbleStatueMaker.productStock = {}; MarbleStatueMaker.buildings = {}; MarbleStatueMaker.maker = nil; MarbleStatueMaker.activeMaking = {}; MarbleStatueMaker.totalProducts = 0; MarbleStatueMaker.dayTimer = 0
function MarbleStatueMaker.init() MarbleStatueMaker.marbleStock=18; MarbleStatueMaker.chiselStock=12; MarbleStatueMaker.silverStock=8; MarbleStatueMaker.goldStock=6; MarbleStatueMaker.jewelStock=6; MarbleStatueMaker.pearlStock=4; MarbleStatueMaker.productStock={}; MarbleStatueMaker.buildings={}; MarbleStatueMaker.maker=nil; MarbleStatueMaker.activeMaking={}; MarbleStatueMaker.totalProducts=0; MarbleStatueMaker.dayTimer=0; print("[MarbleStatueMaker] Royal Marble Statue Maker System initialized (6 products, 4 buildings)") end
function MarbleStatueMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MarbleStatueMaker.maker={name=n or ("Kipar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kipar najet: %s (spretnost: %d)",MarbleStatueMaker.maker.name,s),"success") end; return true end
function MarbleStatueMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MarbleStatueMaker.build(id) local ok,e=MarbleStatueMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MarbleStatueMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MarbleStatueMaker.getQualityBonus() local b=0; for _,bd in ipairs(MarbleStatueMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MarbleStatueMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.marbleCost and MarbleStatueMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.chiselCost and MarbleStatueMaker.chiselStock<(d.chiselCost or 0) then return false,"Premalo dlet" end; if d.silverCost and MarbleStatueMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MarbleStatueMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MarbleStatueMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MarbleStatueMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MarbleStatueMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MarbleStatueMaker.maker then return false,"Potreben kipar" end; return true end
function MarbleStatueMaker.make(pt,qty) qty=qty or 1; local ok,e=MarbleStatueMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.marbleCost then MarbleStatueMaker.marbleStock=MarbleStatueMaker.marbleStock-d.marbleCost*qty end; if d.chiselCost then MarbleStatueMaker.chiselStock=MarbleStatueMaker.chiselStock-d.chiselCost*qty end; if d.silverCost then MarbleStatueMaker.silverStock=MarbleStatueMaker.silverStock-d.silverCost*qty end; if d.goldCost then MarbleStatueMaker.goldStock=MarbleStatueMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MarbleStatueMaker.jewelStock=MarbleStatueMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MarbleStatueMaker.pearlStock=MarbleStatueMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MarbleStatueMaker.maker then t=math.max(1,t-math.floor(MarbleStatueMaker.maker.skill/12)) end; table.insert(MarbleStatueMaker.activeMaking,{id="marblestatue_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MarbleStatueMaker.completeMaking(m) local q=1.0+(MarbleStatueMaker.getQualityBonus()/100); if MarbleStatueMaker.maker then q=q+(MarbleStatueMaker.maker.skill/150) end; q=math.min(2.5,q); MarbleStatueMaker.productStock[m.productType]=(MarbleStatueMaker.productStock[m.productType] or 0)+m.quantity; MarbleStatueMaker.totalProducts=MarbleStatueMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MarbleStatueMaker.maker then MarbleStatueMaker.maker.itemsMade=MarbleStatueMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MarbleStatueMaker.maker.skill=math.min(100,MarbleStatueMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kip izklesan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"marblestatue.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function MarbleStatueMaker.update(dt) if not _G.state then return end; MarbleStatueMaker.dayTimer=MarbleStatueMaker.dayTimer+dt; if MarbleStatueMaker.dayTimer>=30 then MarbleStatueMaker.dayTimer=0; for i=#MarbleStatueMaker.activeMaking,1,-1 do local m=MarbleStatueMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MarbleStatueMaker.completeMaking(m); table.remove(MarbleStatueMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MarbleStatueMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MarbleStatueMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MarbleStatueMaker.getStats() return {marbleStock=MarbleStatueMaker.marbleStock,chiselStock=MarbleStatueMaker.chiselStock,silverStock=MarbleStatueMaker.silverStock,goldStock=MarbleStatueMaker.goldStock,jewelStock=MarbleStatueMaker.jewelStock,pearlStock=MarbleStatueMaker.pearlStock,productStock=MarbleStatueMaker.productStock,numBuildings=#MarbleStatueMaker.buildings,hasMaker=MarbleStatueMaker.maker~=nil,makerName=MarbleStatueMaker.maker and MarbleStatueMaker.maker.name or "—",makerSkill=MarbleStatueMaker.maker and MarbleStatueMaker.maker.skill or 0,activeMaking=#MarbleStatueMaker.activeMaking,totalProducts=MarbleStatueMaker.totalProducts} end
return MarbleStatueMaker
